import pytest

from your_module import compose


def test_compose_applies_multiple_functions_right_to_left():
    def add_one(x):
        return x + 1

    def double(x):
        return x * 2

    def square(x):
        return x**2

    # add_one(double(square(3))) == add_one(double(9)) == 19
    assert compose(add_one, double, square)(3) == 19


def test_compose_invokes_functions_in_reversed_order():
    calls = []

    def f(x):
        calls.append("f")
        return x + "f"

    def g(x):
        calls.append("g")
        return x + "g"

    def h(x):
        calls.append("h")
        return x + "h"

    result = compose(f, g, h)("")

    assert result == "hgf"
    assert calls == ["h", "g", "f"]


def test_compose_with_single_function():
    def strip(value):
        return value.strip()

    assert compose(strip)("  hello  ") == "hello"


def test_compose_with_no_functions_returns_identity():
    identity = compose()

    obj = {"key": "value"}

    assert identity(obj) is obj
    assert identity(123) == 123


def test_compose_allows_intermediate_type_changes():
    def get_id(record):
        return record["id"]

    def stringify(value):
        return f"id={value}"

    def wrap(text):
        return {"label": text}

    assert compose(wrap, stringify, get_id)({"id": 7}) == {"label": "id=7"}


def test_compose_passes_none_as_normal_value():
    def return_none(_):
        return None

    def replace_none(value):
        return "fallback" if value is None else value

    assert compose(replace_none, return_none)("ignored") == "fallback"


def test_compose_propagates_exception_and_stops_chain():
    class BoomError(Exception):
        pass

    calls = []

    def outer_should_not_run(x):
        calls.append("outer")
        return x

    def failing(x):
        calls.append("failing")
        raise BoomError("boom")

    def inner_runs_first(x):
        calls.append("inner")
        return x

    with pytest.raises(BoomError, match="boom"):
        compose(outer_should_not_run, failing, inner_runs_first)(10)

    assert calls == ["inner", "failing"]


def test_compose_with_non_callable_raises_type_error():
    with pytest.raises(TypeError):
        compose(lambda x: x, 42)("value")


def test_compose_with_function_requiring_wrong_number_of_args_raises_type_error():
    def needs_two_args(a, b):
        return a + b

    with pytest.raises(TypeError):
        compose(needs_two_args)(1)


def test_composed_function_requires_exactly_one_argument():
    composed = compose(lambda x: x)

    with pytest.raises(TypeError):
        composed()

    with pytest.raises(TypeError):
        composed(1, 2)
